//! Equirectangular ASCII earth bitmap.
//!
//! Adapted from [SecKC-MHN-Globe](https://github.com/n0xa/SecKC-MHN-Globe)
//! (BSD-2-Clause). 120×60 grid: `#` = land, space = ocean.
//! Longitude −180…+180, latitude +90…−90 (top to bottom).

pub const EARTH_WIDTH: usize = 120;
pub const EARTH_HEIGHT: usize = 60;

/// Land/ocean bitmap rows (exactly [`EARTH_HEIGHT`] strings of length [`EARTH_WIDTH`]).
pub fn earth_bitmap() -> &'static [&'static str] {
    &[
        "                                                                                                                        ",
        "                                                                                                                        ",
        "                                                                                                                        ",
        "                             # ####### #################                                    #                           ",
        "                       #    #   ### #################            ###                                                    ",
        "                      ###  ## ####       ############ #                        ##         ########        #####         ",
        "                  ## ###   #  ### ##      ###########                         #    #### ################   ###          ",
        "      ######## ###### #### # #  #  ###     #########              #######        # ## ##################################",
        " ### ###########################    ####   #####      #          ####### ###############################################",
        "      ########################       ##    ####                #### ####################################################",
        "      ### # #################      ##        #                ##### # ##########################################  ##    ",
        "                ##############     #####                   #     #  #######################################      ##     ",
        "                 ################ #######                # #   ###########################################      ##      ",
        "                  ########################                 ################################################             ",
        "                    ###################  ##                ################################################             ",
        "                   ################### #                    ##########  ####  ############################              ",
        "                   ##################                    ##### ##  ###    ### ##########################                ",
        "                   #################                     ###       # ######## ######################  #    #            ",
        "                    ###############                       #  ###       ##############################  #  #             ",
        "                     #############                        ######        #############################                   ",
        "                       ######## #                        ############################################                   ",
        "                      # ####     #                      ##################### #######################                   ",
        "                       # ###      #                    ################# ######    #################                    ",
        "                         ###  #   #                    ################## ######     ####  #####                        ",
        "                          #####   # #                  ################## #####      ###    ####                        ",
        "                             ####                      ################### ###       ##      ####   #                   ",
        "                               #    #                  ####################           #      # ##                       ",
        "                                #  #####                #####################         #      # #     ##                 ",
        "                                   ######                #### ###############          #      #    #                    ",
        "                                   ########                     ############                 ##   ##                    ",
        "                                  #########                     ###########                   #  ####                   ",
        "                                  #############                 ##########                    ##### #     ##            ",
        "                                 ################                ########                                  ## #         ",
        "                                  ###############                #########                         ## #    # #          ",
        "                                   #############                 #########                                              ",
        "                                   ############                  #########  #                         # ##  #           ",
        "                                     ##########                 #########  ##                        ########           ",
        "                                     ##########                  #######   ##                      ###########     #    ",
        "                                     ########                    #######   #                      #############         ",
        "                                     #######                     ######                           ##############        ",
        "                                     #######                      #####                            #############        ",
        "                                     ######                       ####                             ###   ######         ",
        "                                    #####                                                                  ####       # ",
        "                                    #####                                                                              #",
        "                                    ###                                                                      #        # ",
        "                                    ###                                                                             ##  ",
        "                                    ##                                                                                  ",
        "                                   ##                                                                                   ",
        "                                    ##                                                                                  ",
        "                                                                                                                        ",
        "                                                                                                                        ",
        "                                                                                                                        ",
        "                                       #                                                                                ",
        "                                      #                                #  ##########   ########################         ",
        "                                   #####                 ########################## #################################   ",
        "                  # ## #   #############              #############################################################     ",
        "        ## #########################             ##################################################################     ",
        "           ######################## #  #  ##     #################################################################      ",
        "    ##################################################################################################################  ",
        "########################################################################################################################",
    ]
}

/// Sample the earth bitmap at geographic coordinates.
pub fn sample_earth_at(lat: f64, lon: f64) -> char {
    let map = earth_bitmap();
    let lat_norm = (lat + 90.0) / 180.0;
    let lon_norm = (lon + 180.0) / 360.0;
    let y = ((lat_norm * (EARTH_HEIGHT as f64 - 1.0)).round() as isize)
        .clamp(0, EARTH_HEIGHT as isize - 1) as usize;
    let x = ((lon_norm * (EARTH_WIDTH as f64 - 1.0)).round() as isize)
        .clamp(0, EARTH_WIDTH as isize - 1) as usize;
    map[y].chars().nth(x).unwrap_or(' ')
}
